import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';

const root = fileURLToPath(new URL('.', import.meta.url));
const student = join(root, 'student.mjs');
const expected = {
  valid:{case:'valid',class:'success',attempts:1,action:'accept'},
  invalid:{case:'invalid',class:'validation',attempts:1,action:'fix_request'},
  rate:{case:'rate',class:'success',attempts:3,action:'accept',reconciled:true},
  'spend-cap':{case:'spend-cap',class:'spend_cap',attempts:1,action:'restore_access'},
  billing:{case:'billing',class:'billing',attempts:1,action:'restore_billing'},
  permission:{case:'permission',class:'permission',attempts:1,action:'repair_authorization'},
  overload:{case:'overload',class:'overload',attempts:3,action:'retry_exhausted'},
  changed:{case:'changed',class:'validation',attempts:1,action:'fix_request'}
};

function run(args) {
  return spawnSync(process.execPath, [student, ...args], {cwd:root, encoding:'utf8'});
}

let passed = 0;
for (const name of Object.keys(expected)) {
  const result = run([name]);
  let actual;
  try { actual = JSON.parse(result.stdout); }
  catch { actual = {parse_error:result.stderr.trim()}; }
  const ok = result.status === 0 && JSON.stringify(actual) === JSON.stringify(expected[name]);
  console.log(`${ok?'PASS':'FAIL'} ${name} expected=${JSON.stringify(expected[name])} actual=${JSON.stringify(actual)} exit=${result.status}`);
  if (ok) passed += 1;
}

const missing = run([]);
const missingOk = missing.status === 1 && missing.stderr.trim() === 'usage: node student.mjs <case>';
console.log(`CHECK missing-input ${missingOk?'PASS':'FAIL'} exit=${missing.status}`);
const unknown = run(['not-a-case']);
const unknownOk = unknown.status === 1 && unknown.stderr.trim() === 'unknown case';
console.log(`CHECK unknown-input ${unknownOk?'PASS':'FAIL'} exit=${unknown.status}`);
console.log(`RESULT ${passed}/${Object.keys(expected).length}`);
process.exit(passed === Object.keys(expected).length && missingOk && unknownOk ? 0 : 1);
