import { readFile } from 'node:fs/promises';

const name = process.argv[2];
if (!name) {
  console.error('usage: node reference.mjs <case>');
  process.exit(1);
}

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

let cases;
try {
  cases = JSON.parse(await readFile(new URL('./fixtures/cases.json', import.meta.url), 'utf8'));
  if (!isRecord(cases)) throw new TypeError('invalid fixture store');
} catch {
  console.error('fixture error');
  process.exit(1);
}
if (!Object.hasOwn(cases, name)) {
  console.error('unknown case');
  process.exit(1);
}
const fixture = cases[name];
if (!isRecord(fixture) || !Array.isArray(fixture.events) || !fixture.events.every(isRecord)) {
  console.error('fixture error');
  process.exit(1);
}

const MAX_TOTAL_ATTEMPTS = 3;
let attempts = 0;
let reconciled = false;
let last;

for (const event of fixture.events) {
  if (attempts >= MAX_TOTAL_ATTEMPTS) break;
  attempts += 1;
  last = event;

  if (event.kind === 'success') {
    const output = {case:name,class:'success',attempts,action:'accept'};
    if (reconciled) output.reconciled = true;
    console.log(JSON.stringify(output));
    process.exit(0);
  }

  if (event.status === 400 || event.status === 413) {
    console.log(JSON.stringify({case:name,class:'validation',attempts,action:'fix_request'}));
    process.exit(0);
  }
  if (event.status === 401) {
    console.log(JSON.stringify({case:name,class:'authentication',attempts,action:'repair_credentials'}));
    process.exit(0);
  }
  if (event.status === 402) {
    console.log(JSON.stringify({case:name,class:'billing',attempts,action:'restore_billing'}));
    process.exit(0);
  }
  if (event.status === 403) {
    console.log(JSON.stringify({case:name,class:'permission',attempts,action:'repair_authorization'}));
    process.exit(0);
  }
  if (event.status === 429 && event.normalizedCategory === 'spend_cap') {
    console.log(JSON.stringify({case:name,class:'spend_cap',attempts,action:'restore_access'}));
    process.exit(0);
  }

  if (event.sideEffect === 'unknown') {
    if (event.reconciliation !== 'not_applied') {
      console.log(JSON.stringify({case:name,class:'unknown_side_effect',attempts,action:'reconcile_before_retry'}));
      process.exit(0);
    }
    reconciled = true;
  }

  const transient = event.status === 429 || event.status === 500 || event.status === 504 || event.status === 529;
  if (!transient) {
    console.log(JSON.stringify({case:name,class:'unknown',attempts,action:'escalate'}));
    process.exit(0);
  }
}

const finalClass = last?.status === 429 ? 'rate_limit' : last?.status === 529 ? 'overload' : 'transient';
console.log(JSON.stringify({case:name,class:finalClass,attempts,action:'retry_exhausted'}));
